  "claim_id": "C006",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C006.component",
    "value": "Late returns are a possible contributor to late starts.",
    "scope": "A hypothesis to investigate, not an established contributor.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span identifies late returns as a possible contributor and explicitly labels the contributors as hypotheses."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "Linked booking and return records, together with classification of equipment availability at scheduled start, permit investigation of repeated stage-specific delays, including recurring readiness delays despite calendar availability.",
    "scope": "Assume these candidate observations occur. Retain missing values and unresolved cases; historical comparisons require comparable definitions and coverage. The patterns provide practical investigative evidence, not causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
